```javascript
function findLargestNumber(arr) {
    if (arr.length === 0) return null; // Handle empty array
    let max = arr[0];
    for (let i = 1; i < arr.length; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}
```

